function T(text, o={}){ return new TextRun({ text, font:FONT, size:22, ...o }); }
function para(children, o={}){ return new Paragraph({ children, spacing:{after:120, line:276}, ...o }); }
function body(text){ return new Paragraph({ children:[T(text)], spacing:{after:120, line:276}, alignment:AlignmentType.JUSTIFIED }); }
function authorNote(text){ return new Paragraph({ spacing:{after:120,line:276},
  shading:{type:ShadingType.CLEAR, fill:"FFF2CC"},
  children:[new TextRun({text:"[AUTHORS → "+text+"]", italics:true, color:"9C6500", size:20, font:FONT})]}); }
function img(path, w, h, type){ return new Paragraph({ alignment:AlignmentType.CENTER, spacing:{before:120,after:60},
  children:[new ImageRun({ type, data:fs.readFileSync(path), transformation:{width:w, height:h} })]}); }
function legend(num, rest){ return new Paragraph({ spacing:{after:160,line:276}, children:[
  new TextRun({text:"Fig. "+num+" ", bold:true, font:FONT, size:20}),
  new TextRun({text:rest, font:FONT, size:20})]}); }

// table builder: rows = array of arrays; first row header
function makeTable(rows, widths){
  const total = widths.reduce((a,b)=>a+b,0);
  const trs = rows.map((r,ri)=> new TableRow({ tableHeader: ri===0, children: r.map((c,ci)=>
    new TableCell({ width:{size:widths[ci], type:WidthType.DXA},
      shading: ri===0 ? {type:ShadingType.CLEAR, fill:"D9E2F3"} : undefined,
      children:[ new Paragraph({ spacing:{after:20,line:240}, children:[ new TextRun({ text:String(c),
        bold: ri===0, font:FONT, size:18 }) ] }) ] }))}));
  return new Table({ columnWidths:widths, width:{size:total,type:WidthType.DXA}, rows:trs });
}
function tblCap(text){ return new Paragraph({ spacing:{before:60,after:180,line:252}, children:[
  new TextRun({text:text.split("|")[0], bold:true, font:FONT, size:18}),
  new TextRun({text:text.split("|").slice(1).join("|"), font:FONT, size:18})]}); }

